import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('authorize, approve, capture, refund', async () => {
  const h = await createHost();
  assert.deepEqual(await h.authorize('p', 2), { ok: true });
  assert.equal((await h.authorize('p', 1)).ok, false);
  assert.equal((await h.authorize('q', 3)).ok, false);
  const [e] = await h.pendingEffects();
  assert.deepEqual({ from: e.from, kind: e.kind, data: e.data }, { from: 'p', kind: 'card.authorize', data: { amount: 2 } });
  assert.equal((await h.capture('p', 1)).ok, false);
  await h.completeEffect(e.id, 'ok');
  assert.equal((await h.pendingEffects()).length, 0);
  assert.equal((await h.capture('p', 2)).ok, true);
  assert.equal((await h.void('p')).ok, false);
  assert.equal((await h.refund('p', 1)).ok, true);
  assert.equal((await h.payment('p'))!.status, 'captured');
  assert.equal((await h.refund('p', 2)).ok, false);
  assert.equal((await h.refund('p', 1)).ok, true);
  assert.deepEqual(await h.payment('p'), { status: 'refunded', authorized: 2, captured: 2, refunded: 2, requests: 1 });
  assert.equal(await h.payment('x'), null);
  assert.equal((await h.void('x')).ok, false);
});

test('timeouts retry then fail; late answers ignored', async () => {
  const h = await createHost();
  await h.authorize('p', 1);
  assert.equal((await h.timedOut('p')).ok, true);
  assert.equal((await h.timedOut('p')).ok, true);
  assert.equal((await h.pendingEffects()).length, 3);
  assert.equal((await h.timedOut('p')).ok, true);
  assert.equal((await h.payment('p'))!.status, 'failed');
  assert.equal((await h.payment('p'))!.requests, 3);
  assert.equal((await h.timedOut('p')).ok, false);
  const effects = await h.pendingEffects();
  await h.completeEffect(effects[0].id, 'ok');
  assert.equal((await h.payment('p'))!.status, 'failed');
  assert.equal((await h.pendingEffects()).length, 2);
});

test('first answer decides; void', async () => {
  const h = await createHost();
  await h.authorize('p', 2);
  await h.timedOut('p');
  const [a, b] = await h.pendingEffects();
  await h.completeEffect(b.id, 'ok');
  await h.completeEffect(a.id, 'failed');
  assert.equal((await h.payment('p'))!.status, 'authorized');
  assert.equal((await h.capture('p', 3)).ok, false);
  assert.equal((await h.void('p')).ok, true);
  assert.equal((await h.payment('p'))!.captured, 0);
  await h.authorize('d', 1);
  const [d] = await h.pendingEffects();
  await h.completeEffect(d.id, 'failed');
  assert.equal((await h.payment('d'))!.status, 'declined');
  await h.authorize('c', 1);
  const [c] = await h.pendingEffects();
  await h.completeEffect(c.id, 'ok');
  assert.equal((await h.capture('c', 2)).ok, false);
});

